Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "width": 730,
  "height": 330,
  "padding": {
    "left": 8,
    "top": 18,
    "right": 150,
    "bottom": 8
  },
  "autosize": "none",
  "background": "transparent",
  "signals": [
    {
      "name": "sel",
      "value": null,
      "on": [
        {
          "events": "@pts:mouseover, @hit:mouseover",
          "update": "datum[''Opening Family'']"
        },
        {
          "events": "@pts:mouseout, @hit:mouseout",
          "update": "null"
        }
      ]
    },
    {
      "name": "hx",
      "value": 0,
      "on": [
        {
          "events": "@pts:mouseover, @pts:mousemove, @hit:mouseover, @hit:mousemove",
          "update": "x()"
        }
      ]
    },
    {
      "name": "hy",
      "value": 0,
      "on": [
        {
          "events": "@pts:mouseover, @pts:mousemove, @hit:mouseover, @hit:mousemove",
          "update": "y()"
        }
      ]
    }
  ],
  "data": [
    {
      "name": "dataset"
    },
    {
      "name": "src",
      "source": "dataset",
      "transform": [
        {
          "type": "collect",
          "sort": {
            "field": "Year"
          }
        },
        {
          "type": "joinaggregate",
          "fields": [
            "Year"
          ],
          "ops": [
            "max"
          ],
          "as": [
            "maxYr"
          ]
        }
      ]
    },
    {
      "name": "ends",
      "source": "src",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.Year===datum.maxYr"
        }
      ]
    },
    {
      "name": "cardsrc",
      "source": "src",
      "transform": [
        {
          "type": "filter",
          "expr": "sel != null && datum[''Opening Family''] === sel"
        },
        {
          "type": "formula",
          "as": "ww",
          "expr": "datum[''Opening % White'']*datum[''Total Games'']"
        },
        {
          "type": "formula",
          "as": "wb",
          "expr": "datum[''Opening % Black'']*datum[''Total Games'']"
        },
        {
          "type": "formula",
          "as": "wd",
          "expr": "datum[''Opening % Draw'']*datum[''Total Games'']"
        }
      ]
    },
    {
      "name": "cardrow",
      "source": "cardsrc",
      "transform": [
        {
          "type": "aggregate",
          "groupby": [
            "Opening Family"
          ],
          "fields": [
            "Total Games",
            "ww",
            "wb",
            "wd",
            "Opening Overall Rank",
            "RM First Rank",
            "RM Last Rank",
            "Opening % of Top 5"
          ],
          "ops": [
            "sum",
            "sum",
            "sum",
            "sum",
            "max",
            "max",
            "max",
            "max"
          ],
          "as": [
            "games",
            "sww",
            "swb",
            "swd",
            "rank",
            "fr",
            "lr",
            "pct"
          ]
        },
        {
          "type": "formula",
          "as": "w",
          "expr": "datum.sww/datum.games"
        },
        {
          "type": "formula",
          "as": "b",
          "expr": "datum.swb/datum.games"
        },
        {
          "type": "formula",
          "as": "d",
          "expr": "datum.swd/datum.games"
        }
      ]
    },
    {
      "name": "outcome",
      "source": "cardrow",
      "transform": [
        {
          "type": "fold",
          "fields": [
            "w",
            "b",
            "d"
          ],
          "as": [
            "k",
            "v"
          ]
        },
        {
          "type": "window",
          "ops": [
            "row_number"
          ],
          "as": [
            "i"
          ]
        },
        {
          "type": "formula",
          "as": "label",
          "expr": "datum.i==1?''White'':datum.i==2?''Black'':''Draw''"
        },
        {
          "type": "formula",
          "as": "col",
          "expr": "datum.i==1?''#c9a35a'':datum.i==2?''#2b2620'':''#cabfa3''"
        },
        {
          "type": "pie",
          "field": "v",
          "startAngle": 0,
          "endAngle": 6.28318,
          "sort": false
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "x",
      "type": "point",
      "range": "width",
      "domain": {
        "data": "src",
        "field": "Year",
        "sort": true
      },
      "padding": 0.5
    },
    {
      "name": "y",
      "type": "point",
      "range": "height",
      "domain": [
        1,
        2,
        3,
        4,
        5
      ]
    },
    {
      "name": "color",
      "type": "ordinal",
      "domain": [
        1,
        2,
        3,
        4,
        5
      ],
      "range": [
        "#1f1b15",
        "#a8814a",
        "#6e6450",
        "#9a5a34",
        "#b3a07a"
      ]
    },
    {
      "name": "sz",
      "type": "linear",
      "domain": {
        "data": "src",
        "field": "Opening % of Year"
      },
      "range": [
        120,
        650
      ]
    }
  ],
  "axes": [
    {
      "orient": "bottom",
      "scale": "x",
      "domain": false,
      "ticks": false,
      "labelColor": "#8A8270",
      "labelFont": "Consolas",
      "labelFontSize": 12,
      "labelPadding": 8
    },
    {
      "orient": "left",
      "scale": "y",
      "domain": false,
      "ticks": false,
      "grid": false,
      "labelColor": "#A8956A",
      "labelFont": "Consolas",
      "labelFontSize": 15,
      "encode": {
        "labels": {
          "update": {
            "text": {
              "signal": "''#''+datum.value"
            }
          }
        }
      },
      "labelPadding": -58,
      "labelAlign": "right"
    }
  ],
  "marks": [
    {
      "type": "group",
      "from": {
        "facet": {
          "name": "series",
          "data": "src",
          "groupby": "Opening Family"
        }
      },
      "marks": [
        {
          "type": "line",
          "from": {
            "data": "series"
          },
          "encode": {
            "enter": {
              "x": {
                "scale": "x",
                "field": "Year"
              },
              "y": {
                "scale": "y",
                "field": "Opening Rank by Year"
              },
              "stroke": {
                "scale": "color",
                "field": "Opening Overall Rank"
              },
              "strokeWidth": {
                "value": 3
              },
              "interpolate": {
                "value": "monotone"
              },
              "strokeCap": {
                "value": "round"
              },
              "strokeJoin": {
                "value": "round"
              },
              "opacity": {
                "value": 0.95
              }
            }
          }
        },
        {
          "type": "line",
          "name": "hit",
          "from": {
            "data": "series"
          },
          "interactive": true,
          "encode": {
            "enter": {
              "x": {
                "scale": "x",
                "field": "Year"
              },
              "y": {
                "scale": "y",
                "field": "Opening Rank by Year"
              },
              "stroke": {
                "value": "transparent"
              },
              "strokeWidth": {
                "value": 16
              },
              "interpolate": {
                "value": "monotone"
              }
            }
          }
        }
      ]
    },
    {
      "type": "symbol",
      "from": {
        "data": "src"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "Year"
          },
          "y": {
            "scale": "y",
            "field": "Opening Rank by Year"
          },
          "fill": {
            "scale": "color",
            "field": "Opening Overall Rank"
          },
          "stroke": {
            "value": "#F9F4E9"
          },
          "strokeWidth": {
            "value": 1.5
          },
          "size": {
            "value": 220
          }
        }
      },
      "name": "pts",
      "interactive": true
    },
    {
      "type": "text",
      "from": {
        "data": "ends"
      },
      "encode": {
        "enter": {
          "x": {
            "scale": "x",
            "field": "Year",
            "offset": 26
          },
          "y": {
            "scale": "y",
            "field": "Opening Rank by Year"
          },
          "text": {
            "field": "Opening Family"
          },
          "fill": {
            "scale": "color",
            "field": "Opening Overall Rank"
          },
          "font": {
            "value": "Georgia"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fontSize": {
            "value": 15
          },
          "baseline": {
            "value": "middle"
          },
          "align": {
            "value": "left"
          }
        }
      }
    },
    {
      "type": "group",
      "name": "card",
      "encode": {
        "enter": {
          "x": {
            "value": 150
          },
          "y": {
            "value": 20
          },
          "width": {
            "value": 300
          },
          "height": {
            "value": 208
          }
        },
        "update": {
          "x": {
            "signal": "hx < 360 ? clamp(hx + 18, 4, 580) : clamp(hx - 318, 4, 580)"
          },
          "y": {
            "signal": "clamp(hy - 100, 4, 122)"
          }
        }
      },
      "marks": [
        {
          "type": "rect",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 0
              },
              "y": {
                "value": 0
              },
              "width": {
                "value": 300
              },
              "height": {
                "value": 208
              },
              "cornerRadius": {
                "value": 6
              },
              "fill": {
                "value": "#fffdf8"
              },
              "stroke": {
                "value": "#e3d9c2"
              },
              "strokeWidth": {
                "value": 1
              }
            }
          }
        },
        {
          "type": "rect",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 16
              },
              "y": {
                "value": 15
              },
              "width": {
                "value": 13
              },
              "height": {
                "value": 13
              },
              "cornerRadius": {
                "value": 2
              }
            },
            "update": {
              "fill": {
                "signal": "[''#1f1b15'',''#a8814a'',''#6e6450'',''#9a5a34'',''#b3a07a''][datum.rank-1]"
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 36
              },
              "y": {
                "value": 27
              },
              "font": {
                "value": "Georgia"
              },
              "fontSize": {
                "value": 16
              },
              "fontWeight": {
                "value": "bold"
              },
              "fill": {
                "value": "#2b2620"
              }
            },
            "update": {
              "text": {
                "field": "Opening Family"
              }
            }
          }
        },
        {
          "type": "arc",
          "from": {
            "data": "outcome"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 56
              },
              "y": {
                "value": 102
              },
              "innerRadius": {
                "value": 21
              },
              "outerRadius": {
                "value": 35
              },
              "padAngle": {
                "value": 0.02
              }
            },
            "update": {
              "startAngle": {
                "field": "startAngle"
              },
              "endAngle": {
                "field": "endAngle"
              },
              "fill": {
                "field": "col"
              }
            }
          }
        },
        {
          "type": "rect",
          "from": {
            "data": "outcome"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 108
              },
              "width": {
                "value": 9
              },
              "height": {
                "value": 9
              },
              "cornerRadius": {
                "value": 2
              }
            },
            "update": {
              "y": {
                "signal": "66 + (datum.i-1)*23"
              },
              "fill": {
                "field": "col"
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "outcome"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 123
              },
              "font": {
                "value": "Georgia"
              },
              "fontSize": {
                "value": 11
              },
              "fill": {
                "value": "#5a5346"
              },
              "baseline": {
                "value": "middle"
              }
            },
            "update": {
              "y": {
                "signal": "70 + (datum.i-1)*23"
              },
              "text": {
                "field": "label"
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "outcome"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 170
              },
              "align": {
                "value": "left"
              },
              "font": {
                "value": "Georgia"
              },
              "fontSize": {
                "value": 12
              },
              "fontWeight": {
                "value": "bold"
              },
              "fill": {
                "value": "#2b2620"
              },
              "baseline": {
                "value": "middle"
              }
            },
            "update": {
              "y": {
                "signal": "70 + (datum.i-1)*23"
              },
              "text": {
                "signal": "format(datum.v,''.1%'')"
              }
            }
          }
        },
        {
          "type": "rule",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 16
              },
              "x2": {
                "value": 284
              },
              "y": {
                "value": 150
              },
              "stroke": {
                "value": "#ece3cf"
              },
              "strokeWidth": {
                "value": 1
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 16
              },
              "y": {
                "value": 173
              },
              "font": {
                "value": "Georgia"
              },
              "fontSize": {
                "value": 17
              },
              "fontWeight": {
                "value": "bold"
              },
              "fill": {
                "value": "#2b2620"
              }
            },
            "update": {
              "text": {
                "signal": "format(datum.games,'','')"
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 16
              },
              "y": {
                "value": 188
              },
              "font": {
                "value": "Consolas"
              },
              "fontSize": {
                "value": 10
              },
              "fill": {
                "value": "#a8956a"
              }
            },
            "update": {
              "text": {
                "signal": "''GAMES \u00b7 '' + format(datum.pct,''.0%'') + '' OF TOP-5''"
              }
            }
          }
        },
        {
          "type": "text",
          "from": {
            "data": "cardrow"
          },
          "encode": {
            "enter": {
              "x": {
                "value": 284
              },
              "y": {
                "value": 173
              },
              "align": {
                "value": "right"
              },
              "font": {
                "value": "Consolas"
              },
              "fontSize": {
                "value": 11
              },
              "fill": {
                "value": "#a8956a"
              }
            },
            "update": {
              "text": {
                "signal": "''RANK #'' + datum.rank"
              }
            }
          }
        }
      ]
    }
  ]
}'
